# Generate the 30x30 transformation and validate against the supplied periodic layout.
N=30
g=[[0]*N for _ in range(N)]
tiles=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
starts=[1+7*i for i in range(5)]
# Each visible tile is a 5x5 square: outer frame 4, inner 3x3 color.
for i,r0 in enumerate(starts):
  for j,c0 in enumerate(starts):
    for dr in range(5):
      for dc in range(5):
        r,c=r0+dr,c0+dc
        if r<N and c<N and (dr in (0,4) or dc in (0,4)):
          g[r][c]=4
    if i<4 and j<4:
      for dr in range(1,4):
        for dc in range(1,4):
          g[r0+dr][c0+dc]=tiles[i][j]
# Join minority color 3 horizontally across the full run in tile rows 0 and 2.
for i in (0,2):
  r0=starts[i]
  for j in range(3):
    for dr in range(1,4):
      for dc in (5,6): g[r0+dr][starts[j]+dc]=3
# Join minority color 8 horizontally in tile rows 1 and 3 (columns 1 through 2).
for i in (1,3):
  r0=starts[i]
  for dr in range(1,4):
    for dc in (5,6): g[r0+dr][starts[1]+dc]=8
# Join 3 vertically along tile columns 0 and 3 across tile rows 0..2.
for j in (0,3):
  c0=starts[j]
  for i in range(2):
    for dr in (5,6):
      for dc in range(1,4): g[starts[i]+dr][c0+dc]=3
# Join 8 vertically along tile columns 1 and 2 across tile rows 1..3.
for j in (1,2):
  c0=starts[j]
  for i in (1,2):
    for dr in (5,6):
      for dc in range(1,4): g[starts[i]+dr][c0+dc]=8
assert len(g)==30 and all(len(row)==30 for row in g) and all(0<=x<=9 for row in g for x in row)
# Check the only added cells are intended gap cells and report JSON.
print('{"action":"submit","grid":'+__import__('json').dumps(g,separators=(',',':'))+'}')
